[[nodiscard]] inline constexpr std::optional<std::string_view> qzss_dcx_ex1_target_area_code_ja_lookup(uint16_t id) noexcept {
    uint16_t lo = 0, hi = 1980;
    while (lo < hi) {
        uint16_t mid = static_cast<uint16_t>(lo + (hi - lo) / 2);
        if (QZSS_DCX_EX1_TARGET_AREA_CODE_JA_TABLE[mid].id == id) {
            const char* s = QZSS_DCX_EX1_TARGET_AREA_CODE_JA_TABLE[mid].label;
            return s ? std::optional<std::string_view>(std::string_view{s}) : std::nullopt;
        }
        if (QZSS_DCX_EX1_TARGET_AREA_CODE_JA_TABLE[mid].id < id) lo = mid + 1;
        else hi = mid;
    }
    return std::nullopt;
}
